input.stdin:
:root {
  --bg: #07060b;
  --bg-raised: #0d0914;
  --panel: #0e0a15;
  --panel-2: #120d1a;
  --line: #2e1d3a;
  --line-soft: #24162e;
  --pink: #ff3b9d;
  --pink-soft: #ff9ec7;
  --pink-deep: #b31d68;
  --mint: #7ff7b2;
  --mint-soft: #c4ffdc;
  --mint-deep: #2c9c6a;
  --amber: #ffd166;
  --cyan: #6ed6ff;
  --red: #ff5d6c;
  --text: #f4ecf7;
  --muted: #a28fac;
  --faint: #6d5b79;
  --mono: "IBM Plex Mono", "SFMono-Regular", Consolas, monospace;
  --pixel: "Silkscreen", "IBM Plex Mono", monospace;
  --shadow: 0 18px 50px rgba(0, 0, 0, 0.45);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  color-scheme: dark;
  background: var(--bg);
}

html,
body,
#root {
  min-height: 100%;
}

body {
  margin: 0;
  background:
    radial-gradient(55% 34% at 9% -8%, rgba(255, 59, 157, 0.14), transparent 68%),
    radial-gradient(48% 30% at 96% 4%, rgba(110, 214, 255, 0.08), transparent 62%),
    radial-gradient(60% 40% at 50% 105%, rgba(127, 247, 178, 0.045), transparent 65%),
    var(--bg);
  color: var(--text);
  font-family: var(--mono);
  font-size: 13px;
  line-height: 1.45;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

body::after {
  content: "";
  position: fixed;
  inset: 0;
  z-index: 90;
  pointer-events: none;
  background: repeating-linear-gradient(180deg, rgba(255, 255, 255, 0.018) 0, rgba(255, 255, 255, 0.018) 1px, transparent 1px, transparent 3px);
  opacity: 0.7;
}

::selection {
  background: var(--pink);
  color: #10070d;
}

::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}

::-webkit-scrollbar-track {
  background: #0a0710;
}

::-webkit-scrollbar-thumb {
  background: #3a2547;
  border: 2px solid #0a0710;
}

a {
  color: var(--mint);
}

button {
  font-family: inherit;
}

button:focus-visible {
  outline: 2px solid var(--mint);
  outline-offset: 2px;
}

.app-shell {
  position: relative;
  width: 100%;
  max-width: 1560px;
  margin: 0 auto;
  padding: 20px clamp(14px, 2.3vw, 34px) 30px;
  isolation: isolate;
}

.ambient-grid {
  position: fixed;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.022) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.022) 1px, transparent 1px);
  background-size: 54px 54px;
  -webkit-mask-image: radial-gradient(circle at 50% 0%, #000 0%, transparent 74%);
  mask-image: radial-gradient(circle at 50% 0%, #000 0%, transparent 74%);
}

.tone-mint {
  color: var(--mint);
}

.tone-pink {
  color: var(--pink-soft);
}

.tone-amber {
  color: var(--amber);
}

.tone-cyan {
  color: var(--cyan);
}

.tone-red {
  color: var(--red);
}

/* ---------------- top bar ---------------- */

.topbar {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: clamp(12px, 1.6vw, 24px);
  padding: 12px clamp(12px, 1.3vw, 18px);
  border: 1px solid #3d2549;
  background:
    linear-gradient(90deg, rgba(255, 59, 157, 0.08), transparent 22%, transparent 78%, rgba(255, 59, 157, 0.07)),
    linear-gradient(180deg, #140d1c, #0b0711);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.045);
}

.topbar::before {
  content: "";
  position: absolute;
  left: -1px;
  top: 8px;
  bottom: 8px;
  width: 3px;
  background: var(--pink);
  box-shadow: 0 0 14px rgba(255, 59, 157, 0.8);
}

.brand {
  display: flex;
  align-items: center;
  gap: 11px;
  min-width: 0;
}

.brand-mark {
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  border: 1px solid var(--pink);
  background: #180b1c;
  color: var(--pink);
  box-shadow: inset 0 0 18px rgba(255, 59, 157, 0.16), 0 0 18px rgba(255, 59, 157, 0.08);
}

.brand-mark__svg {
  width: 28px;
  height: 28px;
  display: block;
  filter: drop-shadow(0 0 6px rgba(255, 59, 157, 0.5));
}

.brand-copy {
  min-width: 0;
}

.brand-copy h1 {
  margin: 0;
  font-family: var(--pixel);
  font-size: clamp(14px, 1.35vw, 20px);
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: 0.2px;
  color: #fbf4fc;
  white-space: nowrap;
}

.brand-copy h1 span {
  color: var(--pink);
}

.brand-copy p {
  margin: 4px 0 0;
  font-size: 7.5px;
  line-height: 1.3;
  letter-spacing: 1.2px;
  text-transform: uppercase;
  color: #8f7a9c;
  white-space: nowrap;
}

.brand-live {
  color: var(--mint);
}

.tape {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 4px 11px;
  min-width: 0;
  padding: 6px 16px;
  border-left: 1px dashed #3a2647;
  border-right: 1px dashed #3a2647;
  color: #8f7a9b;
  font-size: 8.5px;
  font-weight: 500;
  letter-spacing: 0.55px;
  text-transform: uppercase;
}

.tape-pair {
  color: var(--cyan);
}

.tape-price {
  color: #f7eff9;
  font-weight: 600;
}

.tape-up {
  color: var(--mint);
}

.tape-down {
  color: var(--red);
}

.tape-sep {
  color: #4f3b5c;
}

.tape-latency {
  color: #6a5777;
}

.topbar-right {
  display: flex;
  align-items: center;
  gap: clamp(10px, 1.3vw, 18px);
  min-width: 0;
}

.bankroll {
  width: clamp(108px, 10vw, 154px);
  min-width: 0;
}

.bankroll-label {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 5px;
  margin-bottom: 4px;
  font-size: 7px;
  letter-spacing: 1.1px;
  color: #786585;
}

.bankroll-label b {
  color: var(--mint);
  font-weight: 500;
}

.bankroll-track {
  position: relative;
  height: 7px;
  border: 1px solid #4c2d5e;
  background: repeating-linear-gradient(90deg, #1a1022 0, #1a1022 4px, #120b18 4px, #120b18 6px);
  overflow: hidden;
}

.bankroll-track span {
  display: block;
  height: 100%;
  background: linear-gradient(90deg, #862454, var(--pink));
  box-shadow: 0 0 10px rgba(255, 59, 157, 0.55);
}

.bankroll-track i {
  position: absolute;
  top: -2px;
  bottom: -2px;
  left: 75.2%;
  width: 2px;
  background: #ffe3f2;
  opacity: 0.8;
}

.session {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding-left: clamp(8px, 1vw, 14px);
  border-left: 1px dashed #3a2647;
  white-space: nowrap;
}

.session span {
  font-size: 7.5px;
  letter-spacing: 1px;
  color: #887494;
}

.session span em {
  font-style: normal;
  color: #5f4c6c;
}

.session strong {
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.6px;
  color: var(--mint);
}

.controls {
  display: flex;
  gap: 6px;
  flex: 0 0 auto;
}

.btn {
  appearance: none;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 30px;
  padding: 0 11px;
  border: 1px solid #51345f;
  background: #180f20;
  color: #cab7d4;
  font-family: var(--pixel);
  font-size: 8px;
  line-height: 1;
  letter-spacing: 0.8px;
  cursor: pointer;
  transition: border-color 0.16s ease, color 0.16s ease, background 0.16s ease, transform 0.16s ease;
}

.btn:hover {
  border-color: var(--pink);
  color: #ffffff;
  transform: translateY(-1px);
}

.btn-hot {
  border-color: #b82a70;
  background: linear-gradient(180deg, #8e1f56, #551032);
  color: #fff4fa;
  box-shadow: 0 0 14px rgba(255, 59, 157, 0.14);
}

.btn-hot:hover {
  background: linear-gradient(180deg, #ad2569, #6d1542);
}

.btn-glyph {
  display: inline-block;
  flex: 0 0 auto;
  color: currentColor;
}

.btn-glyph--pause {
  width: 8px;
  height: 9px;
  border-left: 3px solid currentColor;
  border-right: 3px solid currentColor;
}

.btn-glyph--play {
  width: 0;
  height: 0;
  border-top: 4px solid transparent;
  border-bottom: 4px solid transparent;
  border-left: 6px solid currentColor;
}

/* ---------------- section headers ---------------- */

.dashboard {
  display: block;
}

.section-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px;
  margin: 24px 0 10px;
}

.eyebrow {
  display: block;
  margin-bottom: 4px;
  font-size: 7.5px;
  letter-spacing: 2px;
  color: #9f7daf;
}

.section-title h2 {
  margin: 0;
  font-family: var(--pixel);
  font-size: clamp(13px, 1.25vw, 17px);
  font-weight: 400;
  letter-spacing: 0.4px;
  color: #f6edf8;
}

.section-meta {
  display: flex;
  align-items: center;
  gap: 7px;
  flex-wrap: wrap;
  font-size: 8px;
  letter-spacing: 1px;
  color: #887594;
  white-space: nowrap;
}

.status-dot {
  width: 6px;
  height: 6px;
  background: var(--mint);
  box-shadow: 0 0 9px var(--mint);
  animation: status-pulse 2s ease-in-out infinite;
}

.status-dot--held {
  background: var(--amber);
  box-shadow: 0 0 9px var(--amber);
  animation: none;
}

.meta-divider {
  color: #4f3b5c;
}

/* ---------------- agent grid ---------------- */

.agent-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.accent-pink {
  --accent: var(--pink);
  --accent-glow: rgba(255, 59, 157, 0.3);
}

.accent-mint {
  --accent: var(--mint);
  --accent-glow: rgba(127, 247, 178, 0.24);
}

.accent-cyan {
  --accent: var(--cyan);
  --accent-glow: rgba(110, 214, 255, 0.24);
}

.accent-amber {
  --accent: var(--amber);
  --accent-glow: rgba(255, 209, 102, 0.24);
}

.accent-red {
  --accent: var(--red);
  --accent-glow: rgba(255, 93, 108, 0.26);
}

.value-tone-mint {
  --value: var(--mint);
}

.value-tone-pink {
  --value: #ff9ec7;
}

.value-tone-amber {
  --value: var(--amber);
}

.value-tone-cyan {
  --value: var(--cyan);
}

.value-tone-red {
  --value: var(--red);
}

.agent-card {
  position: relative;
  min-width: 0;
  padding: 10px 12px 8px;
  border: 1px solid #332140;
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.027), transparent 32%),
    linear-gradient(180deg, #110c18, #0b0810);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.028);
  transition: border-color 0.18s ease, transform 0.18s ease, box-shadow 0.18s ease;
}

.agent-card::before,
.agent-card::after {
  content: "";
  position: absolute;
  width: 8px;
  height: 8px;
  pointer-events: none;
  opacity: 0.48;
  transition: opacity 0.18s ease;
}

.agent-card::before {
  top: -1px;
  left: -1px;
  border-top: 1px solid var(--accent);
  border-left: 1px solid var(--accent);
}

.agent-card::after {
  right: -1px;
  bottom: -1px;
  border-right: 1px solid var(--accent);
  border-bottom: 1px solid var(--accent);
}

.agent-card:hover {
  border-color: var(--accent);
  transform: translateY(-1px);
  box-shadow: 0 8px 26px rgba(0, 0, 0, 0.32), inset 0 0 22px rgba(255, 255, 255, 0.018);
}

.agent-card.is-active {
  border-color: var(--accent);
  box-shadow: 0 0 0 1px var(--accent-glow), 0 0 26px var(--accent-glow), inset 0 0 24px rgba(255, 255, 255, 0.025);
}

.agent-card.is-active::before,
.agent-card.is-active::after {
  opacity: 1;
}

.agent-card__head {
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 0;
  padding-bottom: 8px;
  border-bottom: 1px solid #2a1a35;
}

.agent-icon {
  width: 25px;
  height: 25px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  border: 1px solid currentColor;
  color: var(--accent);
  background: #190f21;
  box-shadow: inset 0 0 10px var(--accent-glow);
}

.agent-icon svg {
  width: 15px;
  height: 15px;
  display: block;
}

.agent-name {
  min-width: 0;
  flex: 1;
}

.agent-name h3 {
  margin: 0;
  font-family: var(--pixel);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.6px;
  color: #f6edf8;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.agent-name p {
  margin: 3px 0 0;
  font-size: 7px;
  letter-spacing: 0.55px;
  text-transform: uppercase;
  color: #82708e;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.agent-state {
  display: flex;
  align-items: flex-end;
  gap: 2px;
  height: 12px;
  flex: 0 0 auto;
}

.agent-state i {
  display: block;
  width: 2px;
  background: var(--accent);
  opacity: 0.22;
}

.agent-state i:nth-child(1) {
  height: 4px;
}

.agent-state i:nth-child(2) {
  height: 8px;
}

.agent-state i:nth-child(3) {
  height: 12px;
}

.agent-card.is-active .agent-state i {
  animation: equalize 0.9s steps(3, end) infinite;
}

.agent-card.is-active .agent-state i:nth-child(2) {
  animation-delay: 0.16s;
}

.agent-card.is-active .agent-state i:nth-child(3) {
  animation-delay: 0.32s;
}

.agent-card__body {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 0 8px;
  min-height: 65px;
}

.agent-copy {
  flex: 1;
  min-width: 0;
}

.agent-headline {
  margin: 0;
  font-size: 9.5px;
  line-height: 1.35;
  font-weight: 500;
  letter-spacing: 0.15px;
  color: #ded2e5;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.spark {
  display: block;
  width: 100%;
  height: 26px;
  margin-top: 7px;
  overflow: visible;
}

.spark--mint {
  color: var(--mint);
}

.spark--pink {
  color: var(--pink);
}

.spark--amber {
  color: var(--amber);
}

.spark--cyan {
  color: var(--cyan);
}

.spark--red {
  color: var(--red);
}

.agent-value {
  flex: 0 0 auto;
  max-width: 52%;
  padding-top: 1px;
  font-family: var(--pixel);
  font-size: clamp(16px, 1.55vw, 21px);
  line-height: 1;
  letter-spacing: 0.2px;
  color: var(--value, var(--accent));
  text-shadow: 0 0 18px var(--accent-glow);
  white-space: nowrap;
}

.agent-progress {
  height: 4px;
  background: #25162f;
  box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.6);
  overflow: hidden;
}

.agent-progress span {
  display: block;
  height: 100%;
  background: var(--accent);
  box-shadow: 0 0 8px var(--accent-glow);
  transition: width 0.6s cubic-bezier(0.2, 0.7, 0.2, 1);
}

.agent-card__foot {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  padding-top: 7px;
  font-size: 7px;
  letter-spacing: 0.45px;
  color: #705d7d;
}

.agent-status {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex: 0 0 auto;
  color: #8f7c9b;
  text-transform: uppercase;
  white-space: nowrap;
}

.agent-status i {
  width: 4px;
  height: 4px;
  display: block;
  background: #5e4b6b;
}

.agent-status--active {
  color: var(--accent);
}

.agent-status--active i {
  background: var(--accent);
  box-shadow: 0 0 6px var(--accent);
}

.agent-sub {
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.refresh-glyph {
  width: 11px;
  height: 11px;
  flex: 0 0 auto;
  opacity: 0.5;
}

.agent-card.is-active .refresh-glyph {
  color: var(--accent);
  opacity: 0.9;
  animation: spin 3s linear infinite;
}

/* ---------------- pixel room ---------------- */

.room-card {
  position: relative;
  margin: 16px 0 0;
  border: 1px solid #c2266f;
  background: #0a0710;
  box-shadow:
    0 0 0 1px rgba(255, 59, 157, 0.09),
    0 24px 70px rgba(0, 0, 0, 0.5),
    0 0 44px rgba(255, 59, 157, 0.07);
}

.room-card::before,
.room-card::after {
  content: "";
  position: absolute;
  z-index: 3;
  width: 16px;
  height: 16px;
  pointer-events: none;
}

.room-card::before {
  top: -1px;
  left: -1px;
  border-top: 2px solid #ff72b5;
  border-left: 2px solid #ff72b5;
}

.room-card::after {
  right: -1px;
  bottom: -1px;
  border-right: 2px solid #ff72b5;
  border-bottom: 2px solid #ff72b5;
}

.room-chrome {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  gap: 18px;
  min-width: 0;
  padding: 9px 13px;
  border-bottom: 1px solid #642349;
  background:
    repeating-linear-gradient(90deg, rgba(255, 255, 255, 0.02) 0, rgba(255, 255, 255, 0.02) 1px, transparent 1px, transparent 5px),
    linear-gradient(90deg, #200d22, #100a16 45%, #210d23);
}

.room-title-wrap {
  flex: 0 0 auto;
}

.room-kicker {
  display: block;
  margin-bottom: 3px;
  font-size: 7px;
  letter-spacing: 1.4px;
  color: #ae8ab9;
}

.room-title-wrap h2 {
  margin: 0;
  font-family: var(--pixel);
  font-size: 12px;
  font-weight: 400;
  letter-spacing: 0.8px;
  color: #fff3f9;
  white-space: nowrap;
}

.room-tape {
  display: flex;
  align-items: center;
  gap: 7px 14px;
  flex: 1;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  font-size: 7.5px;
  letter-spacing: 0.65px;
  color: #947c9f;
}

.room-tape span {
  display: inline-flex;
  gap: 5px;
  align-items: center;
  flex: 0 0 auto;
}

.room-tape span + span {
  padding-left: 13px;
  border-left: 1px solid #3a2145;
}

.room-tape b {
  color: #dfd0e5;
  font-weight: 500;
}

.room-tape .tone-mint {
  color: var(--mint);
}

.room-tape .tone-red {
  color: var(--red);
}

.room-tape-active {
  margin-left: auto;
  color: #ffb8d7 !important;
}

.room-tape-active b {
  color: var(--pink) !important;
}

.room-controls {
  display: flex;
  gap: 5px;
  flex: 0 0 auto;
}

.chip-button {
  appearance: none;
  min-height: 25px;
  padding: 0 8px;
  border: 1px solid #6a2b50;
  background: #241020;
  color: #ffc5dd;
  font-family: var(--pixel);
  font-size: 7px;
  letter-spacing: 0.65px;
  cursor: pointer;
  transition: background 0.16s ease, border-color 0.16s ease, color 0.16s ease;
}

.chip-button:hover {
  border-color: var(--pink);
  background: #38152f;
  color: #fff;
}

.chip-button--quiet {
  border-color: #443051;
  background: #160f1d;
  color: #a28dae;
}

.room-viewport {
  position: relative;
  width: 100%;
  aspect-ratio: 1200 / 600;
  min-height: 260px;
  overflow: hidden;
  background: #08050d;
}

.room-svg {
  display: block;
  width: 100%;
  height: 100%;
}

.room-svg text {
  font-family: var(--mono);
}

.room-screen-title {
  font-family: var(--pixel) !important;
  font-size: 8px;
  letter-spacing: 0.7px;
}

.room-axis {
  font-size: 6px;
  fill: #6b8075;
  letter-spacing: 0.2px;
}

.room-price-tag {
  font-family: var(--pixel) !important;
