/* ---------------- motion ---------------- */

@keyframes status-pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.35;
  }
}

@keyframes equalize {
  0% {
    opacity: 0.3;
    transform: scaleY(0.55);
  }
  100% {
    opacity: 1;
    transform: scaleY(1);
  }
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

@keyframes cable-dash {
  to {
    stroke-dashoffset: -44;
  }
}

@keyframes led-blink {
  0%,
  45% {
    opacity: 1;
  }
  46%,
  100% {
    opacity: 0.25;
  }
}

@keyframes screen-sweep {
  0% {
    transform: translateY(0);
    opacity: 0;
  }
  15% {
    opacity: 1;
  }
  82% {
    transform: translateY(140px);
    opacity: 0.3;
  }
  100% {
    transform: translateY(150px);
    opacity: 0;
  }
}

@keyframes station-bob {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-2px);
  }
}

@keyframes ping {
  0% {
    opacity: 0.22;
    transform: scale(0.7);
  }
  55% {
    opacity: 0.75;
    transform: scale(1.2);
  }
  100% {
    opacity: 0;
    transform: scale(1.7);
  }
}

@keyframes pnl-pulse {
  0% {
    opacity: 0.6;
    transform: scale(0.8);
    transform-origin: center;
  }
  100% {
    opacity: 0;
    transform: scale(2);
    transform-origin: center;
  }
}

.app-shell.is-paused .station-bob,
.app-shell.is-paused .fan-blades,
.app-shell.is-paused .cable-flow,
.app-shell.is-paused .rack-led,
.app-shell.is-paused .screen-sweep,
.app-shell.is-paused .agent-ping circle,
.app-shell.is-paused .equity-pulse,
.app-shell.is-paused .status-dot {
  animation-play-state: paused;
}

/* ---------------- 1024 and below ---------------- */

@media (max-width: 1240px) {
  .app-shell {
    padding-top: 16px;
  }

  .topbar {
    grid-template-columns: minmax(0, 1fr) auto;
    row-gap: 8px;
  }

  .tape {
    grid-column: 1 / -1;
    grid-row: 2;
    justify-content: flex-start;
    padding: 7px 0 0;
    border-left: none;
    border-right: none;
    border-top: 1px dashed #332040;
  }

  .topbar-right {
    justify-self: end;
  }

  .agent-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .agent-value {
    font-size: 21px;
  }

  .room-chrome {
    flex-wrap: wrap;
    gap: 7px 14px;
  }

  .room-tape {
    order: 3;
    flex-basis: 100%;
    padding-top: 7px;
    border-top: 1px dashed #3a2045;
    overflow: hidden;
  }

  .room-tape span:nth-child(n + 6) {
    display: none;
  }

  .room-tape-active {
    margin-left: 0;
  }

  .room-controls {
    margin-left: auto;
  }

  .lower-split {
    grid-template-columns: 1fr;
  }

  .threshold-list {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0 24px;
    padding-bottom: 8px;
  }

  .analysis-chart {
    border-right: 1px solid #291a34;
  }

  .room-viewport {
    aspect-ratio: 1200 / 560;
  }
}

@media (max-width: 980px) {
  .analysis-body {
    grid-template-columns: 1fr;
  }

  .analysis-chart {
    border-right: none;
    border-bottom: 1px solid #291a34;
  }

  .analysis-side {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(0, 1.1fr);
    align-content: start;
    gap: 8px 14px;
  }

  .book-head {
    grid-column: 1 / -1;
  }

  .book-rows {
    grid-column: 1;
  }

  .side-grid {
    grid-column: 2;
    grid-row: 2 / span 2;
  }

  .analysis-note {
    grid-column: 1 / -1;
  }

  .candle-chart {
    height: 255px;
  }

  .room-viewport {
    aspect-ratio: 1200 / 520;
  }

  .room-svg {
    object-fit: cover;
  }
}

